pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner) public {
        // admin is the deployer of c, which is this test contract
        vm.prank(address(this));
        bool success = c.setOwner(newOwner);
        // General rule: a completed admin setOwner call always reports success (returns true)
        assertTrue(success, "setOwner must return true");
