// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address newOwner) public {
        // The admin is whoever the constructor saw as msg.sender; in setUp that is this test
        // contract, so only calls from the test contract complete. Keep the domain WIDE:
        // any actor, any newOwner (including zero and c's current owner).
        vm.assume(actor != address(0));

        vm.prank(actor);
        bool ok = false;
        bool success = false;
        try c.setOwner(newOwner) returns (bool s) {
            ok = true;
            success = s;
        } catch {
            ok = false;
        }

        // General rule: if setOwner completes, its returned success flag must be TRUE,
        // regardless of who called or what address was passed.
        assertTrue(!(ok && !success));
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public {
        c = new C();
    }

    function testFuzz_property(address newOwner) public {
        // Widen the domain: any address is admissible as the new owner.
        vm.prank(msg.sender); // msg.sender at setUp-time deployment is the admin of c
        bool ok;
        bool success = true;
        // Drive c through setOwner as the admin, capturing the actual return value.
        vm.prank(c.owner());
        (ok, ) = address(c).call(abi.encodeWithSelector(c.setOwner.selector, newOwner));
        assertTrue(ok && success, "admin call must complete and return true");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(address newOwner) public {
        // admin of c is the deployer (this test contract), set at construction.
        // Drive c through setOwner as the admin, for ANY fuzzed newOwner.
        vm.prank(address(this));
        (bool ok, bytes memory ret) = address(c).call(
            abi.encodeWithSignature("setOwner(address)", newOwner)
        );
        assertTrue(ok && ret.length == 32 && abi.decode(ret, (bool)),
            "setOwner by admin must always return success == true");
    }
}
